"""Local-disk storage for uploaded files. Keys are generated by us, never taken from user input."""

import shutil
import uuid
from pathlib import Path

from app.core.config import settings


def _root() -> Path:
    return Path(settings.UPLOAD_DIR).resolve()


def save(project_id: uuid.UUID, document_id: uuid.UUID, ext: str, data: bytes) -> str:
    key = f"{project_id}/{document_id}{ext}"
    path = _root() / key
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(data)
    return key


def read(key: str) -> bytes:
    return (_root() / key).read_bytes()


def delete(key: str) -> None:
    (_root() / key).unlink(missing_ok=True)


def delete_project(project_id: uuid.UUID) -> None:
    shutil.rmtree(_root() / str(project_id), ignore_errors=True)
